#!/usr/bin/env bash
# Generated by tungo-sdkgen. Do not edit.
#
# Keeps the SDK version identical in the manifest, the in-code constant and
# CHANGELOG.md. Every line that carries the version is marked with the comment
# token "x-release-version"; package.json is handled by name.
#
#   bash scripts/release-version.sh check X.Y.Z          consistency
#   bash scripts/release-version.sh check-release X.Y.Z  consistency + dated CHANGELOG entry
#   bash scripts/release-version.sh set X.Y.Z            rewrite every location
#
# The single-quoted programs below are awk, not shell.
# shellcheck disable=SC2016
set -euo pipefail

MARKER='x-release-version'
MIN_LOCATIONS=2
SEMVER='[0-9]+\.[0-9]+\.[0-9]+'

usage() {
  echo "usage: $0 check|check-release|set X.Y.Z" >&2
  exit 2
}

[[ $# -eq 2 ]] || usage
mode="$1"
version="$2"
[[ "${mode}" == "check" || "${mode}" == "check-release" || "${mode}" == "set" ]] || usage
if [[ ! "${version}" =~ ^${SEMVER}$ ]]; then
  echo "error: version must look like X.Y.Z, got '${version}'" >&2
  exit 2
fi

cd "$(dirname "${BASH_SOURCE[0]}")/.."

marked_files() {
  grep -rlI --fixed-strings \
    --exclude-dir=.git --exclude-dir=node_modules --exclude-dir=target \
    --exclude-dir=build --exclude-dir=dist --exclude-dir=.build \
    --exclude-dir=vendor --exclude-dir=bin --exclude-dir=obj \
    --exclude-dir=.venv --exclude-dir=.gradle --exclude-dir=scripts \
    --exclude='*.md' -e "${MARKER}" . || true
}

rewrite() {
  local file="$1" program="$2" tmp
  tmp="$(mktemp)"
  awk -v v="${version}" -v m="${MARKER}" "${program}" "${file}" >"${tmp}"
  cat "${tmp}" >"${file}"
  rm -f "${tmp}"
}

if [[ "${mode}" == "set" ]]; then
  while IFS= read -r file; do
    [[ -n "${file}" ]] || continue
    rewrite "${file}" 'index($0, m) { sub(/[0-9]+\.[0-9]+\.[0-9]+/, v) } { print }'
  done < <(marked_files)
  if [[ -f package.json ]]; then
    rewrite package.json '!done && /^  "version": "/ { sub(/"version": "[^"]*"/, "\"version\": \"" v "\""); done = 1 } { print }'
  fi
  if [[ -f package-lock.json ]]; then
    rewrite package-lock.json 'seen < 2 && /^ +"version": "/ { sub(/"version": "[^"]*"/, "\"version\": \"" v "\""); seen++ } { print }'
  fi
  echo "version set to ${version}"
  exit 0
fi

locations=0
failures=0

while IFS= read -r file; do
  [[ -n "${file}" ]] || continue
  while IFS= read -r line; do
    locations=$((locations + 1))
    found="$(grep -oE "${SEMVER}" <<<"${line#*:}" | head -n 1 || true)"
    if [[ "${found}" != "${version}" ]]; then
      echo "error: ${file}:${line%%:*} has version '${found}', expected ${version}" >&2
      failures=$((failures + 1))
    fi
  done < <(grep -n --fixed-strings -e "${MARKER}" "${file}")
done < <(marked_files)

if [[ -f package.json ]]; then
  locations=$((locations + 1))
  found="$(grep -m 1 -E '^  "version": "' package.json | grep -oE "${SEMVER}[^\"]*" || true)"
  if [[ "${found}" != "${version}" ]]; then
    echo "error: package.json has version '${found}', expected ${version}" >&2
    failures=$((failures + 1))
  fi
fi

if [[ "${locations}" -lt "${MIN_LOCATIONS}" ]]; then
  echo "error: found ${locations} version location(s), expected at least ${MIN_LOCATIONS} (lines marked '${MARKER}')" >&2
  failures=$((failures + 1))
fi

entry="^## \[${version//./\\.}\] - "
if [[ "${mode}" == "check-release" ]]; then
  if ! grep -qE "${entry}[0-9]{4}-[0-9]{2}-[0-9]{2}$" CHANGELOG.md 2>/dev/null; then
    echo "error: CHANGELOG.md has no dated entry '## [${version}] - YYYY-MM-DD'" >&2
    failures=$((failures + 1))
  fi
elif ! grep -qE "${entry}" CHANGELOG.md 2>/dev/null; then
  echo "error: CHANGELOG.md has no entry '## [${version}]'" >&2
  failures=$((failures + 1))
fi

if [[ "${failures}" -gt 0 ]]; then
  exit 1
fi
echo "version ${version} is consistent in ${locations} location(s) and CHANGELOG.md"
